		let binFloat = clamp(d, 0.0, f32(uniforms.numBins) - 0.001);
		let bin = u32(binFloat);
		let binFrac = binFloat - f32(bin);
		sortKey = u32(binWeights[bin].base + binWeights[bin].divider * binFrac);
